package com.corp.cache;
import java.util.HashMap;
import java.util.Map;

// 缓存编解码模块入口: 命中刷新、标签清理、写缓存三条业务路径
public class main {
    private static final Map<String, String> CACHE_STORE = new HashMap<>();
    private final helper codec = new helper();

    // 入口1: 缓存命中后刷新访问计数(主数据流, 表面直达公共 sink)
    public String onCacheHit(String encodedKey) throws Exception {
        String decoded = codec.decodeKey(encodedKey);
        if (!codec.isSafeIdentifier(decoded)) {
            return "REJECTED";
        }
        codec.touchEntry(decoded);
        return "HIT";
    }

    // 入口2: 管理端按标签批量清理过期缓存(第二入口)
    public int purgeStaleEntries(String rawTag) throws Exception {
        String normalized = codec.normalizeTag(rawTag);
        return codec.evictByTag(normalized);
    }

    // 入口3: 写缓存并持久化索引
    public void putEntry(String key, String value) throws Exception {
        String encoded = codec.encodeValue(value);
        CACHE_STORE.put(key, encoded);
        codec.persistEntry(key, encoded);
    }

    public static void main(String[] args) throws Exception {
        main svc = new main();
        svc.putEntry(args[0], args[1]);
        svc.onCacheHit(args[2]);
        svc.purgeStaleEntries(args[3]);
    }
}
