from helper import sanitize_identifier, validate_token, fetch_report_rows, fetch_summary

app = Flask(__name__)

@app.route("/export", methods=["GET"])
def export_report():
    # 报表导出：支持自定义排序字段与部门过滤
    sort_field = request.args.get("sort", "created_at")
    department = request.args.get("department", "all")
    clean_sort = sanitize_identifier(sort_field)
    clean_dept = validate_token(department)
    if clean_sort is None or clean_dept is None:
        return jsonify({"error": "invalid parameter"}), 400
    rows = fetch_report_rows("reports.db", clean_dept, clean_sort)  # 参数均已通过校验
    return jsonify({"count": len(rows), "rows": rows})

@app.route("/summary", methods=["GET"])
def summary_report():
    # 报表汇总：按报表 ID 查询
    report_id = request.args.get("report_id", "")
    try:
        rid = int(report_id)
    except (ValueError, TypeError):
        return jsonify({"error": "invalid id"}), 400
    row = fetch_summary("reports.db", rid)
    if row is None:
        return jsonify({"error": "not found"}), 404
    return jsonify({"summary": row})

if __name__ == "__main__":
    app.run(host="0.0.0.0", port=8080)
