import (
	"log"
	"net/http"
	"os"
)

var cfg *ConfigCenter
func main() {
	cfg = NewConfigCenter(os.Getenv("CONFIG_CENTER_ADDR"))
	http.HandleFunc("/worker/restart", handleRestart)
	http.HandleFunc("/jvm/gctune", handleGCTune)
	http.HandleFunc("/cache/flush", handleFlush)
	log.Fatal(http.ListenAndServe("127.0.0.1:8080", nil))
}

// 入口1: 查询参数拼成配置键, 取回脚本名后执行
func handleRestart(w http.ResponseWriter, r *http.Request) {
	script := cfg.Fetch(r.URL.Query().Get("ns") + ".worker.restart.script")
	if !IsSafeToken(script) {
		http.Error(w, "bad token", 400)
		return
	}
	if err := RunScript(script); err != nil {
		log.Printf("restart failed: %v", err)
	}
	w.Write([]byte("ok"))
}

// 入口2: 配置中心推送的 JVM 调优参数转发诊断工具
func handleGCTune(w http.ResponseWriter, r *http.Request) {
	if err := ApplyGCFlag(cfg.Fetch("jvm.gc.flag")); err != nil {
		http.Error(w, "tune failed", 500)
	}
	w.Write([]byte("done"))
}
// 入口3: 区域名仅作映射键使用
func handleFlush(w http.ResponseWriter, r *http.Request) {
	region := cfg.Fetch(r.URL.Query().Get("env") + ".cache.region")
	if err := FlushCache(region); err != nil {
		http.Error(w, "flush failed", 500)
	}
	w.Write([]byte("flushed"))
}
