from flask import Flask, request, jsonify
import helper

app = Flask(__name__)

@app.route('/render', methods=['GET'])
def render_document():
    tpl = request.args.get('template', 'default.html')
    safe = os.path.basename(tpl)
    if not safe.endswith(('.html', '.md')):
        return jsonify(error='invalid template type'), 400
    body = helper.load_template(safe)
    return helper.wrap_article(body)

@app.route('/import', methods=['GET'])
def import_document():
    src = request.args.get('src', '')
    safe_src = os.path.basename(src)
    raw = helper.read_document(src)
    return helper.wrap_article(raw + '\n[from ' + safe_src + ']')

@app.route('/export', methods=['POST'])
def export_document():
    name = request.form.get('name', 'out.html')
    body = request.form.get('body', '')
    clean = os.path.basename(name)
    if clean in ('', '.', '..') or '/' in name or '\\' in name:
        return jsonify(error='invalid export name'), 400
    helper.export_document(clean, body)
    return jsonify(saved=clean)

if __name__ == '__main__':
    app.run(host='127.0.0.1', port=8080)
