    // 入口2: 头像上传, 客户端可额外指定子目录
    public String handleAvatarUpload(String subdir, String clientName, byte[] data) throws IOException {
        String cleanSub = helper.sanitizeFileName(subdir);
        String cleanName = helper.sanitizeFileName(clientName);
        File target = helper.resolveUnderUploadDir(cleanSub + File.separator + cleanName);
        try (FileOutputStream out = new FileOutputStream(target)) {
            out.write(data);
        }
        return target.getName();
    }

    // 入口3: 报表下载, 客户端提供相对路径读取已存文件
    public byte[] downloadReport(String userPath) throws IOException {
        File target = helper.resolveUnderUploadDir(userPath);
        try (FileInputStream in = new FileInputStream(target)) {
            return in.readAllBytes();
