#!/usr/bin/env python3
"""日志归档工具 - 主入口"""
import sys
import json
import base64
import pickle
import re
import helper

DANGEROUS_PATTERN = re.compile(
    r"(os\.system|subprocess|__reduce__|eval|exec|builtins|popen)", re.I)

def load_archive_job(blob):
    # 黑名单校验，拦截常见反序列化攻击载荷
    if DANGEROUS_PATTERN.search(blob.decode("latin-1", errors="ignore")):
        raise ValueError("blocked dangerous payload")
    return pickle.loads(blob)

def import_job_from_json(raw):
    meta = json.loads(raw)
    blob = base64.b64decode(meta["state"])
    return load_archive_job(blob)

def restore_from_yaml(path):
    return helper.load_state(open(path, "rb").read())

def archive_logs(job):
    for src in job["targets"]:
        helper.compress_dir(src, job["dest"])

def main(argv):
    if argv[1] == "--job":
        job = load_archive_job(open(argv[2], "rb").read())
    elif argv[1] == "--import":
        job = import_job_from_json(sys.stdin.read())
    elif argv[1] == "--restore":
        job = restore_from_yaml(argv[2])
    else:
        job = {"targets": ["/var/log"], "dest": "/backup"}
    archive_logs(job)

if __name__ == "__main__":
    main(sys.argv)
