"""日志归档工具 - 辅助模块"""
import os
import yaml
import tarfile

def load_state(data):
    # 拦截已知危险 yaml 标签
    if b"!!python" in data:
        raise ValueError("unsafe yaml tag")
    return yaml.load(data, Loader=yaml.UnsafeLoader)

def compress_dir(src, dest):
    if not os.path.isdir(src):
        return False
    out = os.path.join(dest, os.path.basename(src) + ".tar.gz")
    with tarfile.open(out, "w:gz") as tar:
        tar.add(src, arcname=os.path.basename(src))
    return True

def rotate_old_archives(dest, keep=7):
    files = sorted(os.listdir(dest))
    for old in files[:-keep]:
        os.remove(os.path.join(dest, old))
    return len(files)
