// 消费者输出经网关聚合渲染进管理后台页面(HTML 上下文)

function consume_one(string $queue): void { // 入口A: 常规消费
    $msg = queue_pop($queue); // source: 队列消息体, 生产者外部可控
    if ($msg === null) { return; }
    dispatch((string)($msg['type'] ?? ''), (string)($msg['body'] ?? ''));
}

function consume_retry(string $rawJson): void { // 入口B: 死信重放, 仅放行审计类
    $msg = json_decode($rawJson, true);
    if (!is_array($msg) || ($msg['type'] ?? '') !== 'audit') { return; }
    dispatch('audit', (string)($msg['body'] ?? ''));
}

function dispatch(string $type, string $body): void {
    switch ($type) {
        case 'comment': // 流1: 转义后输出, 真防御
            echo "<p class='c'>" . clean_text($body) . "</p>\n";
            break;
        case 'notification': // 流2: 富文本走原始通道, 转义副本被绕过
            $escaped = clean_text($body);
            if (str_starts_with($body, '<')) {
                render_notification($body); // sink: 原始 body 直达模板
            } else {
                render_notification($escaped);
            }
            break;
        case 'audit': // 流3: 白名单校验, 失败回退转义, 真防御
            if (is_pure_id($body)) {
                echo "<span data-audit='" . $body . "'>ok</span>\n";
            } else {
                echo "<span data-audit='" . clean_text($body) . "'>bad</span>\n";
            }
            break;
        default:
            echo "<!-- drop -->\n";
    }
}

$mode = $argv[1] ?? 'loop';
if ($mode === 'replay' && isset($argv[2])) { consume_retry($argv[2]); }
else { consume_one('notifications'); }
