// main.ts - 图片处理流水线: 水印与元数据 SVG 生成服务
import express from 'express';
import { renderTemplate, isSafeTemplateText, PRESET_TEMPLATES } from './helper';

const app = express();
app.use(express.json());

// 入口1: POST /watermark - 用户自定义水印文字
app.post('/watermark', (req, res) => {
  const text = String(req.body?.text ?? '');
  if (!isSafeTemplateText(text)) {
    return res.status(400).json({ error: 'illegal watermark text' });
  }
  // 用户文本直接进入模板渲染
  const svg = renderTemplate(PRESET_TEMPLATES.get('watermark'), { label: text });
  res.type('image/svg+xml').send(svg);
});

// 入口2: GET /meta/:name - 图片文件名写入元数据模板
app.get('/meta/:name', (req, res) => {
  const name = String(req.params?.name ?? '');
  if (!/^[A-Za-z0-9_-]{1,32}$/.test(name)) {
    return res.status(400).json({ error: 'illegal file name' });
  }
  const svg = renderTemplate(PRESET_TEMPLATES.get('meta'), { file: name });
  res.type('image/svg+xml').send(svg);
});

// 入口3: POST /style - 用户按 ID 选择预设模板
app.post('/style', (req, res) => {
  const id = String(req.body?.styleId ?? '');
  const tpl = PRESET_TEMPLATES.get(id);
  if (tpl === undefined) {
    return res.status(400).json({ error: 'unknown style id' });
  }
  res.type('image/svg+xml').send(renderTemplate(tpl, { label: 'IMG' }));
});

app.listen(8080);
