    private static final String IMG_ROOT = "/var/app/images";
    private static final Pattern SAFE_NAME =
        Pattern.compile("^[A-Za-z0-9_-]{1,64}\\.(png|jpg|jpeg)$");
    private static final helper ops = new helper(IMG_ROOT);

    // Entry 1: user picks an image by name for the thumbnail pipeline
    public File loadForThumbnail(String userName) throws IOException {
        if (userName == null || !SAFE_NAME.matcher(userName).matches()) {
            throw new IllegalArgumentException("bad image name");
        }
        File f = ops.resolveUnderRoot(userName);
        return ops.decode(f);
    }

    // Entry 2: batch import driven by manifest entries that may contain ../
    public File loadFromManifest(String manifestEntry) throws IOException {
        Path base = Paths.get(IMG_ROOT).toAbsolutePath().normalize();
        Path target = base.resolve(manifestEntry).normalize();
        if (!target.startsWith(base)) {
            throw new SecurityException("traversal blocked");
        }
        File canon = target.toFile().getCanonicalFile();
        if (!canon.getPath().startsWith(base + File.separator)) {
            throw new SecurityException("symlink escape blocked");
        }
        return ops.decode(canon);
    }

    // Entry 3: store uploaded image; client name only hints the extension
    public File storeUpload(String clientName, byte[] bytes) throws IOException {
        String ext = ops.extractExt(clientName);
        return ops.persistRandom(ext, bytes);
    }
