    // 入口2: 本地缓存, 文件内容进入 unserialize
    public function loadCache(string $key): array
    {
        $blob = @file_get_contents($this->cacheDir . '/' . KeyGuard::cacheFile($key));
        if ($blob === false) { return []; }
        $data = unserialize($blob, ['allowed_classes' => false]);
        return is_array($data) ? $data : [];
    }

    // 入口3: Agent 上报, 请求体进入解码
    public function applyAgentPatch(string $body): array
    {
        $json = json_decode(base64_decode($body, true) ?: '{}', true);
        return is_array($json) ? array_map('strval', $json) : [];
    }
