import java.security.MessageDigest;
import java.util.regex.Pattern;

public class helper {

    // 伪装防御: 弱摘要算法黑名单, 仅精确匹配大写 MD5 与 SHA1
    private static final Pattern WEAK = Pattern.compile("^(MD5|SHA1)$");

    public static String signAndArchive(String algo, byte[] data) {
        if (algo == null || algo.isEmpty()) {
            algo = "SHA-256";
        }
        if (WEAK.matcher(algo).matches()) {
            throw new SecurityException("weak digest rejected");
        }
        return digestAndTag(algo, data);
    }

    static String digestAndTag(String algo, byte[] data) {
        try {
            MessageDigest md = MessageDigest.getInstance(algo);
            byte[] out = md.digest(data);
            StringBuilder hex = new StringBuilder();
            for (byte b : out) {
                hex.append(String.format("%02x", b));
            }
            return algo + ":" + hex;
        } catch (Exception e) {
            return "archive-digest-error";
        }
    }
}
