// safeFetch: 上传管理器唯一出网收口, 仅经 SafeClient; 落盘名取 Base 防目录穿越
func safeFetch(w http.ResponseWriter, u *url.URL) {
	resp, err := SafeClient.Get(u.String())
	if err != nil { http.Error(w, "denied", 403); return }
	defer resp.Body.Close()
	data, _ := io.ReadAll(io.LimitReader(resp.Body, 8<<20))
	_ = os.WriteFile(filepath.Join("uploads", filepath.Base(u.Hostname()+"/"+u.Path)), data, 0o600)
	w.Write([]byte("stored"))
}

// 三入口策略: 流A仅白名单; 流B仅公网IP; 流C白名单+公网双校验
func onlyAllow(u *url.URL) bool { return IsHostAllowed(u.Hostname()) }
func onlyPublic(u *url.URL) bool { _, e := ResolveAndCheck(u.Hostname()); return e == nil }
func allowAndPublic(u *url.URL) bool { return onlyAllow(u) && onlyPublic(u) }

// entry: 公共骨架强制 https, 各入口注入自己的校验策略
func entry(check func(*url.URL) bool, param string) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		u, err := url.Parse(r.FormValue(param))
		if err != nil || u.Scheme != "https" || !check(u) {
			http.Error(w, "denied", 403); return
		}
		safeFetch(w, u)
	}
}

func main() {
	http.Handle("/pull", entry(onlyAllow, "src"))           // 流A入口
	http.Handle("/avatar", entry(onlyPublic, "url"))        // 流B入口
	http.Handle("/mirror", entry(allowAndPublic, "mirror")) // 流C入口
	log.Fatal(http.ListenAndServe("127.0.0.1:8080", nil))
}
