public class main {
    private static final File UPLOAD_DIR = new File("/var/app/uploads");
    private final helper sanitizer = new helper();

    // 入口1: 单文件上传, 文件名来自HTTP请求参数
    public String handleUpload(String fileName, InputStream data) throws Exception {
        if (!sanitizer.isSafeName(fileName)) { throw new IllegalArgumentException("rejected"); }
        String cleaned = sanitizer.stripPath(fileName);
        File target = new File(UPLOAD_DIR, cleaned);
        if (!sanitizer.isInsideBase(target, UPLOAD_DIR)) { throw new SecurityException("traversal blocked"); }
        try (FileOutputStream out = new FileOutputStream(target)) {
            byte[] buf = new byte[8192];
            int n;
            while ((n = data.read(buf)) > 0) { out.write(buf, 0, n); }
        }
        return target.getName();
    }

    // 入口2: 批量导入, 键为客户端提供的原始文件名
    public Map<String, String> handleBatch(Map<String, InputStream> files) throws Exception {
        Map<String, String> saved = new HashMap<>();
        for (Map.Entry<String, InputStream> e : files.entrySet()) {
            saved.put(e.getKey(), handleUpload(e.getKey(), e.getValue()));
        }
        return saved;
    }

    // 入口3: 重命名接口, 新名与旧名均来自用户输入
    public String handleRename(String oldName, String newName) throws Exception {
        String safe = sanitizer.forceUuidName(newName);
        File src = new File(UPLOAD_DIR, sanitizer.stripPath(oldName));
        File dst = new File(UPLOAD_DIR, safe);
        if (!sanitizer.isInsideBase(src, UPLOAD_DIR) || !sanitizer.isInsideBase(dst, UPLOAD_DIR)) {
            throw new SecurityException("blocked");
        }
        if (!src.renameTo(dst)) { throw new IllegalStateException("rename failed"); }
        return dst.getName();
    }
}
