function load_deploy_snapshot(string $raw, string $sig): ?array {
    $key = getenv('OPSTOOL_STATE_KEY');
    if ($key === false || $key === '' || $raw === '') {
        return null;
    }
    $expect = hash_hmac('sha256', $raw, $key);
    if (!hash_equals($expect, $sig)) {
        return null;
    }
    $obj = unserialize($raw, ['allowed_classes' => false]);
    return is_array($obj) ? $obj : null;
