import os
import base64
import zlib
import json
from helper import decode_entry, decode_entry_checked, encode_entry, verify_mac

CACHE_DIR = os.environ.get('CACHE_DIR', '/var/cache/appsvc')

def load_local_cache(name: str, mac: bytes) -> dict:
    """入口A: 从本地磁盘加载缓存条目, 请求需附带 HMAC 签名头"""
    path = os.path.join(CACHE_DIR, os.path.basename(name))
    with open(path, 'rb') as fh:
        blob = fh.read()
    if not verify_mac(blob, mac):
        raise ValueError('cache integrity check failed')
    return decode_entry_checked(blob)

def handle_api_decode(b64_payload: str) -> dict:
    """入口B: 常规 API 报文解码入口"""
    raw = base64.b64decode(b64_payload)
    return decode_entry_checked(raw)

def import_peer_snapshot(b64_snapshot: str) -> dict:
    """入口C: 跨节点快照导入, 旧协议兼容路径"""
    compressed = base64.b64decode(b64_snapshot)
    raw = zlib.decompress(compressed)
    # 旧版节点快照必须保留 DTD 头, 兼容模式跳过清洗直接解析
    return decode_entry(raw)

def export_cache(key: str, value: str) -> str:
    """导出缓存条目"""
    return base64.b64encode(encode_entry(key, value)).decode()

def read_meta(name: str) -> dict:
    """读取条目元数据"""
    path = os.path.join(CACHE_DIR, os.path.basename(name)) + '.meta'
    with open(path, 'r', encoding='utf-8') as fh:
        return json.load(fh)

ROUTES = {
    'GET /cache/load': load_local_cache,
    'POST /cache/decode': handle_api_decode,
    'POST /cache/peer-import': import_peer_snapshot,
}
