    // 入口1: 配置中心长连接推送回调
    public void onConfigPush(String key, String rawValue) {
        if (rawValue == null || !SAFE_VALUE.matcher(rawValue).matches()) {
            return;
        }
        renderer.renderNotify(key, rawValue);
    }

    // 入口2: 本地快照恢复
    public void restoreSnapshot(String snapshotLine) {
        int idx = snapshotLine == null ? -1 : snapshotLine.indexOf('=');
        String value = idx >= 0 ? snapshotLine.substring(idx + 1) : "";
        if (!SAFE_VALUE.matcher(value).matches()) {
            value = "invalid";
        }
        String neutralized = value.replace("${", "").replace("#{", "");
        renderer.renderNotify("snapshot.key", neutralized);
    }

    // 入口3: 管理端覆盖接口
    public void applyOverride(String userValue) {
        String v = userValue == null ? "" : userValue.trim();
        if (!SAFE_VALUE.matcher(v).matches()) {
            v = "default";
        }
        Map<String, String> ctx = new HashMap<>();
        ctx.put("value", v);
        renderer.renderWith("alert: ${value}", ctx);
    }

    public static void main(String[] args) {
        new main().onConfigPush("cpu.threshold", "90");
        new main().restoreSnapshot("cpu.threshold=95");
        new main().applyOverride("disk usage high");
    }
}
