var argRe = regexp.MustCompile(`^[A-Za-z0-9._]+$`) // 防御C: 参数字符白名单
// 防御A: 工具名固定白名单
var allowedTools = map[string]bool{"ping": true, "df": true, "uptime": true}
// 防御B: 任务模板编译期固定, 输入仅作键索引, 永不拼接
var jobTemplates = map[string]string{
	"backup":  "tar -czf /tmp/b.tgz /data",
	"cleanup": "find /tmp -mtime +7 -delete",
}
func sanitizeArg(s string) string {
	if argRe.MatchString(s) && !strings.HasPrefix(s, "-") {
		return s
	}
	return ""
}

func runTool(name string, args []string) (string, error) {
	if !allowedTools[name] {
		return "", fmt.Errorf("tool not allowed")
	}
	for _, a := range args {
		if !argRe.MatchString(a) {
			return "", fmt.Errorf("bad arg")
		}
	}
	out, err := exec.Command(name, args...).Output() // sink1
	return string(out), err
}

func runJob(name string) (string, error) {
	tpl, ok := jobTemplates[name]
	if !ok {
