// 数据同步工作线程: 三条入口汇聚到同一反序列化 sink
public class main {
    static final Set<String> TRUSTED = new HashSet<>(Arrays.asList("sync.SyncTask", "sync.SyncMeta"));

    // 入口1: 消息队列同步 —— 主数据流, 强制白名单过滤
    static void onQueueMessage(byte[] payload) throws Exception {
        ObjectInputFilter filter = info -> TRUSTED.contains(info.className())
                ? ObjectInputFilter.Status.ALLOWED : ObjectInputFilter.Status.REJECTED;
        Object obj = helper.deserializeFiltered(payload, filter);
        helper.runSyncTask(obj);
    }

    // 入口2: 对端快照恢复 —— 第二入口, 伪 HMAC 后直连无过滤 sink
    static void restoreFromPeer(byte[] snapshot, String peerMac) throws Exception {
        if (!helper.verifyHmac(snapshot, peerMac)) {
            return;
        }
        Object obj = helper.deserialize(snapshot);
        helper.runSyncTask(obj);
    }

    // 入口3: 本地缓存重放 —— 自产数据, 同样强制过滤
    static void replayLocalCache() throws Exception {
        byte[] blob = helper.readLocalCache("sync_worker.cache");
        ObjectInputFilter filter = info -> TRUSTED.contains(info.className())
                ? ObjectInputFilter.Status.ALLOWED : ObjectInputFilter.Status.REJECTED;
        Object obj = helper.deserializeFiltered(blob, filter);
        helper.runSyncTask(obj);
    }

    public static void main(String[] args) throws Exception {
        byte[] msg = helper.readSocket(args.length > 0 ? args[0] : "peer-sync:9100");
        String mode = args.length > 1 ? args[1] : "queue";
        if (mode.equals("restore")) restoreFromPeer(msg, args.length > 2 ? args[2] : "");
        else if (mode.equals("replay")) replayLocalCache();
        else onQueueMessage(msg);
    }
}
