import fs from 'fs';
import path from 'path';

const CACHE_ROOT = path.resolve(__dirname, 'cache_store');

// 编码：缓存键映射为磁盘文件名，base64url 输出仅含字母数字与 - _
export function encodeKeyToFilename(key) {
  return Buffer.from(String(key), 'utf8').toString('base64url');
}

// 解码：分片引用还原为原始文件名，供调试接口按引用取回分片
export function decodeShardRef(ref) {
  try {
    return Buffer.from(String(ref), 'base64').toString('utf8');
  } catch (e) {
    return '';
  }
}

// 防御工具：仅放行不含路径分隔符与点号的文件名，供各入口按需选用
export function isSafeCacheName(name) {
  return /^[A-Za-z0-9_-]+$/.test(String(name));
}

// 唯一磁盘读取汇聚点：文件名拼入缓存根目录后读取条目内容
export function readCacheEntry(filename) {
  const target = path.join(CACHE_ROOT, String(filename));
  return fs.readFileSync(target, 'utf8');
}
