// safeValueRe 仅放行字母数字点横线下划线，阻断 shell 元字符
var safeValueRe = regexp.MustCompile(`^[A-Za-z0-9._-]{1,64}$`)

// fetchFromCenter 配置中心客户端 SDK 拉取原始配置值（环境变量模拟）
func fetchFromCenter(key string) string {
	return os.Getenv("CFG_CENTER_" + key)
}

func main() {
	// 入口1: 配置中心远程值 -> 健康检查命令
	raw := fetchFromCenter("healthcheck_cmd")
	if !safeValueRe.MatchString(raw) {
		log.Printf("reject unsafe config value")
		return
	}
	out, err := runHealthCheck(raw)
	if err != nil {
		log.Printf("health check failed: %v", err)
		return
	}
	fmt.Println(out)

	// 入口2: 环境变量覆盖 -> 探测提供方
	provider := os.Getenv("HEALTHCHECK_PROVIDER")
	if !isAllowedProvider(provider) {
		log.Printf("provider not allowed")
		return
	}
	fmt.Println(runProviderProbe(provider))

	// 入口3: 命令行参数 -> 本地工具调用
	if len(os.Args) > 1 && safeValueRe.MatchString(os.Args[1]) {
		fmt.Println(execToolFixed(os.Args[1]))
	}
}
