package main

import (
	"fmt"
	"os/exec"
	"strings"
)

// isAllowedProvider 枚举白名单，仅放行固定提供方
func isAllowedProvider(p string) bool {
	switch p {
	case "prometheus", "zabbix", "nagios":
		return true
	}
	return false
}

// runHealthCheck 二次前缀校验 + 参数数组不经 shell
func runHealthCheck(cmd string) (string, error) {
	if !strings.HasPrefix(cmd, "check_") {
		return "", fmt.Errorf("cmd prefix invalid")
	}
	out, err := exec.Command("/usr/local/bin/nagios-cli", cmd).Output()
	return string(out), err
}

// runProviderProbe 白名单值参数化传递
func runProviderProbe(provider string) string {
	out, _ := exec.Command("probe", "--provider", provider).Output()
	return string(out)
}

// execToolFixed 参数数组传递，不经 shell 解释
func execToolFixed(arg string) string {
	out, _ := exec.Command("/opt/tools/cfgtool", "get", arg).Output()
	return string(out)
}
