    $raw = $_GET['channel'] ?? 'generic';
    $allow = ['generic', 'slack', 'teams'];
    if (in_array($raw, $allow, true)) {
        return $raw;
    }
    return 'generic';
}

function resolveTemplate(): string
{
    $raw = $_COOKIE['template'] ?? 'default';
    $safe = basename((string) $raw);
    if (preg_match('#^[A-Za-z0-9_-]{1,40}$#', $safe)) {
        return $safe;
    }
    return 'default';
}

function resolveAdapter(): string
{
    $raw = $_POST['adapter'] ?? '';
    return str_replace('../', '', (string) $raw); // normalize traversal
}

